const items = $input.all();
const processedItems = [];

function parseMoney(value) {
    if (!value) return 0;
    let number = String(value).replace(/[^0-9.,-]/g, '');
    const lastComma = number.lastIndexOf(',');
    const lastDot = number.lastIndexOf('.');

    // Colombian format: 5.000,00 -> 5000.00
    if (lastComma > lastDot) {
        number = number.replace(/\./g, '').replace(',', '.');
    } else {
        // US format: 1,674,300.00 -> 1674300.00; 5000 -> 5000
        number = number.replace(/,/g, '');
    }

    const parsed = Number(number);
    return Number.isFinite(parsed) ? parsed : 0;
}

function classifyMovement(text) {
    const normalized = String(text || '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, ' ');

    const outgoing = [
        /compraste/, /compra realizada/, /enviaste/, /transferiste/,
        /transferencia realizada/, /pago realizado/, /pago exitoso/,
        /retiro/, /debito/, /debitado/, /salio de tu cuenta/
    ];
    const incoming = [
        /recibiste/, /recibido/, /te consignaron/, /consignacion recibida/,
        /transferencia recibida/, /abono recibido/, /ingreso a tu cuenta/,
        /deposito recibido/, /se acredito/, /acreditado en tu cuenta/
    ];

    if (outgoing.some(pattern => pattern.test(normalized))) {
        return { direction: 'outgoing', transaction_type: 'expense', is_received: false, is_outgoing: true, classification_reason: 'El correo indica compra, envío o débito' };
    }
    if (incoming.some(pattern => pattern.test(normalized))) {
        return { direction: 'incoming', transaction_type: 'income', is_received: true, is_outgoing: false, classification_reason: 'El correo indica recepción o abono' };
    }
    return { direction: 'unknown', transaction_type: 'unknown', is_received: false, is_outgoing: false, classification_reason: 'No se pudo identificar entrada o salida' };
}

for (const item of items) {
    const email = item.json;
    const body = email.textPlain || email.text || email.snippet || email.body || '';
    const subject = email.Subject || email.subject || 'Sin asunto';
    const fullText = `${subject}\n${body}`;
    const movement = classifyMovement(fullText);

    const amountMatch = fullText.match(/\$\s*([\d.,]+)/);
    const amount = parseMoney(amountMatch ? amountMatch[1] : 0);

    const refMatch = fullText.match(/(?:comprobante|referencia|aprobaci[óo]n|transacci[óo]n)\s*#?\s*([A-Z0-9-]+)/i);
    const reference = refMatch
        ? refMatch[1]
        : 'BC-MAIL-' + (email.id || email.historyId || Math.random().toString(36).slice(2, 11));

    const nameMatch = fullText.match(/\bde\s+(.+?)\s+en\s+tu\s+cuenta/i);
    const paymentDate = email.internalDate
        ? new Date(Number(email.internalDate))
        : new Date();

    processedItems.push({
        json: {
            reference,
            amount,
            bank: 'Bancolombia',
            payer_name: nameMatch ? nameMatch[1].trim() : 'Desconocido',
            payment_date: paymentDate.toISOString(),
            email_subject: subject,
            raw_email: body,
            direction: movement.direction,
            transaction_type: movement.transaction_type,
            is_received: movement.is_received,
            is_outgoing: movement.is_outgoing,
            classification_reason: movement.classification_reason,
            classification_confidence: movement.direction === 'unknown' ? 'low' : 'high'
        }
    });
}

return processedItems;

// 1. Obtener la respuesta de texto de Gemini
const rawText = $input.item.json.content.parts[0].text;

// 2. Limpiar los bloques de Markdown ```json y ```
const cleanJsonText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. Convertir el texto a un Objeto JSON de JavaScript
const parsedData = JSON.parse(cleanJsonText);

// 4. Retornar los datos limpios
return {
  json: {
    reference: parsedData.reference,
    amount: parseFloat(parsedData.amount)
  }
};
